"use strict";

const mongoose = require("mongoose");
const { newId } = require("../../../utils/ids");

/**
 * Ids are 24-char hex strings generated by the app rather than ObjectIds, and
 * timestamps are ISO strings rather than Dates. Both choices keep documents
 * byte-identical between the mongo and local drivers, so switching drivers
 * never changes the shape of an API response.
 */
const userSchema = new mongoose.Schema(
  {
    _id: { type: String, default: newId },
    firstName: { type: String, required: true, trim: true },
    lastName: { type: String, required: true, trim: true },
    email: { type: String, required: true, unique: true, lowercase: true, trim: true, index: true },
    passwordHash: { type: String, required: true },
    role: { type: String, enum: ["admin", "member"], default: "member", index: true },
    accentColor: { type: String, default: "#5b8cff" },
    // No schema default on purpose — the local driver has no schema, so the
    // quota is set explicitly by the auth service from configuration instead.
    storageQuotaBytes: { type: Number },
    lastLoginAt: { type: String, default: null },
    isActive: { type: Boolean, default: true },
    createdAt: { type: String },
    updatedAt: { type: String },
  },
  { versionKey: false, timestamps: false, _id: false }
);

module.exports = userSchema;
